interface InitMessage {
  type: "init";
  values: ArrayBuffer;
  width: number;
  height: number;
}

interface CalculateMessage {
  type: "calculate";
  id: number;
  seaLevelM: number;
}

let values = new Int16Array();
let width = 0;
let height = 0;

self.onmessage = (event: MessageEvent<InitMessage | CalculateMessage>) => {
  const message = event.data;
  if (message.type === "init") {
    values = new Int16Array(message.values);
    width = message.width;
    height = message.height;
    return;
  }
  let wetArea = 0;
  let totalArea = 0;
  let weightedDepth = 0;
  for (let y = 0; y < height; y += 1) {
    const latitude = Math.PI / 2 - ((y + 0.5) / height) * Math.PI;
    const weight = Math.cos(latitude);
    for (let x = 0; x < width; x += 1) {
      const elevation = values[y * width + x];
      totalArea += weight;
      if (elevation < message.seaLevelM) {
        wetArea += weight;
        weightedDepth += (message.seaLevelM - elevation) * weight;
      }
    }
  }
  const marsAreaKm2 = 4 * Math.PI * 3389.5 * 3389.5;
  self.postMessage({
    id: message.id,
    coverage: wetArea / totalArea,
    volumeKm3: (weightedDepth / totalArea) * marsAreaKm2 / 1000
  });
};
